def should_use_color(opts):
    c = opts.get("color","auto")
    if c == "always":
        return True
    if c == "never":
        return False
    # auto: enabled only if stdout is tty
    return sys.stdout.isatty()

def should_use_decorations(opts):
    d = opts.get("decorations","auto")
    if d == "always":
        return True
    if d == "never":
        return False
    # auto: only if tty
    return sys.stdout.isatty()

def should_use_pager(opts):
    p = opts.get("paging","auto")
    if p == "always":
        return True
